draw.viewbox(0, 0, 760, 340);

// Layering groups to ensure proper z-index ordering
const layer_ellipses = draw.group();
const layer_edges = draw.group();
const layer_nodes = draw.group();
const layer_arrows = draw.group();
const layer_labels = draw.group();

/**
 * Renders mathematical expressions gracefully.
 * Splits on letters/Θ to apply italics just to variables.
 */
function createMathNode(parent, x, y, expr, bg = "circle", w = 80, h = 40) {
    let g = parent.group();
    if (bg === "box") {
        g.rect(w, h).center(x, y).fill('#dcdcdc').radius(2);
    } else if (bg === "circle") {
        g.circle(36).center(x, y).fill('#fff').opacity(0.9);
    } else if (bg === "none") {
        g.rect(w, h).center(x, y).fill('#fff').opacity(0.85); // Invisible backing to mask lines
    }

    g.text(function(add) {
        let parts = expr.split(/([a-zA-ZΘ]+)/);
        parts.forEach(p => {
            if (!p) return;
            if (/^[a-zA-ZΘ]+$/.test(p)) {
                add.tspan(p).font({ style: 'italic' });
            } else {
                add.tspan(p).font({ style: 'normal' });
            }
        });
    }).font({ family: 'Georgia, serif', size: 16 }).center(x, y);

    return g;
}

function connect(parent, x1, y1, x2, y2) {
    return parent.line(x1, y1, x2, y2).stroke({ width: 1.5, color: '#1a1a1a' });
}

// ─── Diagram Components ──────────────────────────────────────────────────────

// Tree A (Bad partition followed by Good partition)
let nA_n = createMathNode(layer_nodes, 200, 60, 'n');
let nA_0 = createMathNode(layer_nodes, 80, 150, '0');
let nA_n1 = createMathNode(layer_nodes, 300, 150, 'n-1');
let nA_box1 = createMathNode(layer_nodes, 180, 260, '(n-1)/2 - 1', 'box', 105, 40);
let nA_box2 = createMathNode(layer_nodes, 370, 260, '(n-1)/2', 'box', 80, 40);

let eA1 = connect(layer_edges, 200, 60, 80, 150);
let eA2 = connect(layer_edges, 200, 60, 300, 150);
let eA3 = connect(layer_edges, 300, 150, 180, 260);
let eA4 = connect(layer_edges, 300, 150, 370, 260);

// Tree B (Consistently balanced partition)
let nB_n = createMathNode(layer_nodes, 580, 60, 'n');
let nB_box1 = createMathNode(layer_nodes, 480, 200, '(n-1)/2', 'box', 80, 40);
let nB_box2 = createMathNode(layer_nodes, 680, 200, '(n-1)/2', 'box', 80, 40);

let eB1 = connect(layer_edges, 580, 60, 480, 200);
let eB2 = connect(layer_edges, 580, 60, 680, 200);

// Ellipses (Cost grouping)
let ellipseA = layer_ellipses.ellipse(60, 40).center(200, 60).fill({ color: '#dcdcdc' });
let ellipseB = layer_ellipses.ellipse(60, 40).center(580, 60).fill({ color: '#dcdcdc' });

// Dotted Arrows & Cost Labels
const arrowMarker = draw.marker(14, 14, function(add) { 
    add.path('M0,3 L8,6 L0,9 Z').fill('#222'); 
}).ref(7, 6);

let arrowA = layer_arrows.line(240, 60, 380, 60).stroke({ width: 2.5, color: '#222', dasharray: '4,4' }).marker('end', arrowMarker);
let arrowB = layer_arrows.line(620, 60, 700, 60).stroke({ width: 2.5, color: '#222', dasharray: '4,4' }).marker('end', arrowMarker);

let lbl_thetaA = createMathNode(layer_labels, 410, 60, 'Θ(n)', 'none', 45, 24);
let lbl_thetaB = createMathNode(layer_labels, 730, 60, 'Θ(n)', 'none', 45, 24);

// Captions
layer_labels.text('(a)').font({ family: 'Georgia, serif', size: 18 }).center(200, 320);
layer_labels.text('(b)').font({ family: 'Georgia, serif', size: 18 }).center(580, 320);

// ─── Interaction & Animation Logic ───────────────────────────────────────────

let nodesA_level1 = [nA_0, nA_n1, eA1, eA2];
let nodesA_level2 = [nA_box1, nA_box2, eA3, eA4];
let nodesB_level1 = [nB_box1, nB_box2, eB1, eB2];

/**
 * Transitions the diagram to show specific levels of the recursion tree.
 */
function applyState(level, dur = 400) {
    if (level >= 1) {
        nodesA_level1.forEach(el => el.animate(dur).opacity(1));
        nodesB_level1.forEach(el => el.animate(dur).opacity(1));

        // Tree A cost encompasses two alternating levels
        ellipseA.animate(dur).attr({ rx: 90, ry: 35, cx: 250, cy: 105 }).transform({ rotate: 42, cx: 250, cy: 105 });
        arrowA.animate(dur).plot(320, 105, 390, 105);
        lbl_thetaA.animate(dur).transform({ translateX: 10, translateY: 45 }); // Relative to original center (410, 60)
    } else {
        nodesA_level1.forEach(el => el.animate(dur).opacity(0));
        nodesB_level1.forEach(el => el.animate(dur).opacity(0));

        // Cost evaluates root only
        ellipseA.animate(dur).attr({ rx: 30, ry: 20, cx: 200, cy: 60 }).transform({ rotate: 0, cx: 200, cy: 60 });
        arrowA.animate(dur).plot(240, 60, 380, 60);
        lbl_thetaA.animate(dur).transform({ translateX: 0, translateY: 0 });
    }

    if (level >= 2) {
        nodesA_level2.forEach(el => el.animate(dur).opacity(1));
    } else {
        nodesA_level2.forEach(el => el.animate(dur).opacity(0));
    }
}

// Tooltips on hover for educational value
ellipseA.css('cursor', 'pointer').on('mousemove', e => showTooltip('Combined partitioning work over two alternating levels is bounded by Θ(n)', e)).on('mouseleave', hideTooltip);
ellipseB.css('cursor', 'pointer').on('mousemove', e => showTooltip('Work for a single balanced partition step is Θ(n)', e)).on('mouseleave', hideTooltip);
[nA_box1, nA_box2, nB_box1, nB_box2].forEach(box => {
    box.css('cursor', 'pointer').on('mousemove', e => showTooltip('Remaining subproblem size successfully reduced to roughly half', e)).on('mouseleave', hideTooltip);
});

// Demo player sequence
const demoSteps = [
    { narration: "Both scenarios start with a subarray of size n. The work to partition this array is Θ(n).", level: 0 },
    { narration: "A balanced partition (b) divides the problem in half immediately. A bad partition (a) is highly lopsided, only peeling off one element.", level: 1 },
    { narration: "If the bad partition is immediately followed by a good one, the remaining subproblems (grey boxes) are roughly half the original size. The combined work for these two steps in (a) is still bounded by Θ(n).", level: 2 }
];

let currentStep = 0;

function syncDemoUI() {
    document.getElementById('demoNarration').textContent = demoSteps[currentStep].narration;
    document.getElementById('stepLabel').textContent = `Step ${currentStep + 1} / 3`;
    document.getElementById('recursionLevelInput').value = currentStep;
    document.getElementById('recursionLevelVal').textContent = ['Start', 'First partition', 'Second partition'][currentStep];
    applyState(currentStep, 400);
}

window.prevStep = function() {
    if (currentStep > 0) { currentStep--; syncDemoUI(); }
};

window.nextStep = function() {
    if (currentStep < demoSteps.length - 1) { currentStep++; syncDemoUI(); }
};

window.update_recursionLevel = function(val) {
    currentStep = val;
    syncDemoUI();
};

window.trigger_highlightCost = function() {
    ellipseA.animate(250).fill('#ffe066').animate(650).fill('#dcdcdc');
    ellipseB.animate(250).fill('#ffe066').animate(650).fill('#dcdcdc');
};

// Initialize immediate state natively
applyState(0, 0);

window.__markRendered();
// @FIGURE_CODE_END

