// @FIGURE_CODE_BEGIN
const draw = SVG().addTo('#container').size('100%', '100%');
draw.viewbox(0, 0, 800, 360);

// Layering groups to ensure proper z-index ordering
const layer_ellipses = draw.group();
const layer_edges = draw.group();
const layer_nodes = draw.group();
const layer_arrows = draw.group();
const layer_labels = draw.group();

/**
 * Renders mathematical expressions gracefully.
 * Uses an absolute positioning technique so the text group is internally centered.
 * Avoids default white backgrounds so text composites cleanly over grouping ellipses.
 */
function createMathNode(parent, x, y, expr, bg = "none", w = 80, h = 40) {
    let g = parent.group();
    if (bg === "box") {
        g.rect(w, h).center(0, 0).fill('#e0e0e0');
    }

    g.text(function(add) {
        let parts = expr.split(/([a-zA-Z]+)/);
        parts.forEach(p => {
            if (!p) return;
            if (/^[a-zA-Z]+$/.test(p)) {
                add.tspan(p).font({ style: 'italic' });
            } else {
                add.tspan(p).font({ style: 'normal' });
            }
        });
    }).font({ family: 'Georgia, "Times New Roman", serif', size: 20 }).center(0, 0);

    g.transform({ translateX: x, translateY: y });
    return g;
}

function connect(parent, x1, y1, x2, y2) {
    return parent.line(x1, y1, x2, y2).stroke({ width: 1.5, color: '#1a1a1a' });
}

// ─── Diagram Components ──────────────────────────────────────────────────────

// Tree A (Bad partition followed by Good partition)
let nA_n = createMathNode(layer_nodes, 150, 60, 'n');
let nA_0 = createMathNode(layer_nodes, 60, 160, '0');
let nA_n1 = createMathNode(layer_nodes, 260, 160, 'n-1');
let nA_box1 = createMathNode(layer_nodes, 150, 260, '(n-1)/2 - 1', 'box', 125, 40);
let nA_box2 = createMathNode(layer_nodes, 330, 260, '(n-1)/2', 'box', 95, 40);

// Edges A (shortened so they do not intersect text)
let eA1 = connect(layer_edges, 140, 71, 70, 149);
let eA2 = connect(layer_edges, 161, 70, 242, 144);
let eA3 = connect(layer_edges, 245, 175, 175, 240);
let eA4 = connect(layer_edges, 272, 177, 315, 240);

// Tree B (Consistently balanced partition)
let nB_n = createMathNode(layer_nodes, 550, 110, 'n');
let nB_box1 = createMathNode(layer_nodes, 430, 210, '(n-1)/2', 'box', 95, 40);
let nB_box2 = createMathNode(layer_nodes, 670, 210, '(n-1)/2', 'box', 95, 40);

// Edges B (shortened)
let eB1 = connect(layer_edges, 532, 125, 450, 190);
let eB2 = connect(layer_edges, 568, 125, 650, 190);

// Ellipses (Cost grouping - placed carefully on background layer)
let ellipseA = layer_ellipses.ellipse(190, 80).center(205, 110).fill({ color: '#e0e0e0' });
let ellipseB = layer_ellipses.ellipse(60, 50).center(550, 110).fill({ color: '#e0e0e0' });

// Dotted Arrows & Cost Labels (Heavy & Blocky styling)
const arrowMarker = draw.marker(16, 16, function(add) { 
    add.path('M0,3 L10,8 L0,13 Z').fill('#222'); 
}).ref(9, 8);

let arrowA = layer_arrows.line(0, 0, 0, 0).stroke({ width: 3.5, color: '#222', dasharray: '6,6' }).marker('end', arrowMarker);
let arrowB = layer_arrows.line(585, 110, 675, 110).stroke({ width: 3.5, color: '#222', dasharray: '6,6' }).marker('end', arrowMarker);

let lbl_thetaA = createMathNode(layer_labels, 415, 110, 'Θ(n)');
let lbl_thetaB = createMathNode(layer_labels, 715, 110, 'Θ(n)');

// Captions
layer_labels.text('(a)').font({ family: 'Georgia, "Times New Roman", serif', size: 20 }).center(200, 320);
layer_labels.text('(b)').font({ family: 'Georgia, "Times New Roman", serif', size: 20 }).center(550, 320);

// ─── Interaction & Animation Logic ───────────────────────────────────────────

let nodesA_level1 = [nA_0, nA_n1, eA1, eA2];
let nodesA_level2 = [nA_box1, nA_box2, eA3, eA4];
let nodesB_level1 = [nB_box1, nB_box2, eB1, eB2];

/**
 * Transitions the diagram between varying levels of the recursion tree.
 */
function applyState(level, dur = 400) {
    const applyOpacity = (el, val) => dur ? el.animate(dur).opacity(val) : el.opacity(val);
    const applyAttr = (el, props) => dur ? el.animate(dur).attr(props) : el.attr(props);
    const applyTransform = (el, props) => dur ? el.animate(dur).transform(props) : el.transform(props);
    const applyPlot = (el, ...args) => dur ? el.animate(dur).plot(...args) : el.plot(...args);

    if (level >= 1) {
        nodesA_level1.forEach(el => applyOpacity(el, 1));
        nodesB_level1.forEach(el => applyOpacity(el, 1));
    } else {
        nodesA_level1.forEach(el => applyOpacity(el, 0));
        nodesB_level1.forEach(el => applyOpacity(el, 0));
    }

    if (level >= 2) {
        nodesA_level2.forEach(el => applyOpacity(el, 1));

        // Tree A cost encompasses two alternating levels
        applyAttr(ellipseA, { rx: 95, ry: 40, cx: 205, cy: 110 });
        applyTransform(ellipseA, { rotate: 42, cx: 205, cy: 110 });
        applyPlot(arrowA, 300, 110, 380, 110);
        applyTransform(lbl_thetaA, { translateX: 415, translateY: 110 });
    } else {
        nodesA_level2.forEach(el => applyOpacity(el, 0));

        // Cost evaluates root only
        applyAttr(ellipseA, { rx: 30, ry: 25, cx: 150, cy: 60 });
        applyTransform(ellipseA, { rotate: 0, cx: 150, cy: 60 });
        applyPlot(arrowA, 185, 60, 265, 60);
        applyTransform(lbl_thetaA, { translateX: 300, translateY: 60 });
    }
}

// Tooltips on hover for educational value
ellipseA.css('cursor', 'pointer').on('mousemove', e => showTooltip('Combined partitioning work over two alternating levels is bounded by Θ(n)', e)).on('mouseleave', hideTooltip);
ellipseB.css('cursor', 'pointer').on('mousemove', e => showTooltip('Work for a single balanced partition step is Θ(n)', e)).on('mouseleave', hideTooltip);
[nA_box1, nA_box2, nB_box1, nB_box2].forEach(box => {
    box.css('cursor', 'pointer').on('mousemove', e => showTooltip('Remaining subproblem size successfully reduced to roughly half', e)).on('mouseleave', hideTooltip);
});

// Demo player sequence
const demoSteps = [
    { narration: "Both scenarios start with a subarray of size n. The work to partition this array is Θ(n).", level: 0 },
    { narration: "A balanced partition (b) divides the problem in half immediately. A bad partition (a) is highly lopsided, only peeling off one element.", level: 1 },
    { narration: "If the bad partition is immediately followed by a good one, the remaining subproblems (grey boxes) are roughly half the original size. The combined work for these two steps in (a) is still bounded by Θ(n).", level: 2 }
];

let currentStep = 2; // Initialize to final expanded state

function syncDemoUI() {
    let narration = document.getElementById('demoNarration');
    let label = document.getElementById('stepLabel');
    let input = document.getElementById('recursionLevelInput');
    let val = document.getElementById('recursionLevelVal');

    if (narration) narration.textContent = demoSteps[currentStep].narration;
    if (label) label.textContent = `Step ${currentStep + 1} / 3`;
    if (input) input.value = currentStep;
    if (val) val.textContent = ['Start', 'First partition', 'Second partition'][currentStep];

    applyState(currentStep, 400);
}

window.prevStep = function() {
    if (currentStep > 0) { currentStep--; syncDemoUI(); }
};

